static inline uint8_t crc8_update(uint8_t crc, uint8_t b) {
  crc ^= b;
  for (uint8_t i=0;i<8;i++) crc = (crc & 1) ? (crc>>1) ^ 0x8C : (crc>>1);
  return crc;
