+
+    FILE *fp = fopen(manifest_path, "rb");
+    if (!fp) {
+        // Fallback to demo game if manifest missing
+        add_game("sample-rotation", "Demo-Setup Rotation", 2, 4);
+        s_manifest_loaded = false;
+        return;
